// Inject base64 images
  const logoB64 = '';
  const waleedB64 = '';
  const mohammedB64 = '';

  document.getElementById('nav-logo-img').src = 'data:image/png;base64,' + logoB64;
  document.getElementById('booking-logo-img').src = 'data:image/png;base64,' + logoB64;
  document.getElementById('footer-logo-img').src = 'data:image/png;base64,' + logoB64;
  document.getElementById('waleed-img').src = 'data:image/png;base64,' + waleedB64;
  document.getElementById('mohammed-img').src = 'data:image/png;base64,' + mohammedB64;

  function openBooking(e) {
    e.preventDefault();
    document.getElementById('booking-page').classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeBooking() {
    document.getElementById('booking-page').classList.remove('active');
    document.body.style.overflow = '';
    document.getElementById('booking-phone').classList.remove('visible');
  }

  function revealPhone() {
    document.getElementById('booking-phone').classList.add('visible');
  }

  function togglePhone() {
    document.getElementById('contact-phone').classList.toggle('visible');
  }

  // Close booking on background click
  document.getElementById('booking-page').addEventListener('click', function(e) {
    if (e.target === this) closeBooking();
  });

  // Smooth scroll for nav
  document.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', function(e) {
      const href = this.getAttribute('href');
      if (href === '#') return;
      const target = document.querySelector(href);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth' });
      }
    });
  });